// Собираем запрос к qwen3-vl:8b. Страницы из pdf-render уходят
// одним сообщением (images[]). Формат ответа жёстко задан JSON-схемой:
// только позиции (items), шапку не извлекаем (решение владельца 2026-10-05).
// Промт — единый источник: /data/shared/prompts/extract_items_system.txt
// (тот же файл читает tests/run_eval.py — eval мерит продовый промт).
const fs = require('fs');
const render = $input.first().json;
const body = $('Webhook').first().json.body;
if (!render.pages || !render.pages.length) {
  throw new Error('RENDER_FAIL: ' + JSON.stringify(render).slice(0, 400));
}
const systemPrompt = fs.readFileSync('/data/shared/prompts/extract_items_system.txt', 'utf8').trim();
const payload = {
  model: 'qwen3-vl:8b-instruct-q8_0',
  think: false,
  stream: false,
  format: {
    type: 'object',
    properties: {
      items: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            line_no: { type: 'integer' },
            item_name: { type: 'string' },
            unit: { type: ['string', 'null'] },
            quantity: { type: ['number', 'null'] },
            price: { type: ['number', 'null'] }
          },
          required: ['line_no', 'item_name'],
          additionalProperties: false
        }
      }
    },
    required: ['items'],
    additionalProperties: false
  },
  options: { temperature: 0, num_ctx: 16384 },
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: 'Извлеки позиции накладной.', images: render.pages }
  ]
};
return { json: { payload: payload, doc_id: body.doc_id, file_name: body.file_name } };

// Разбор и валидация ответа VLM. Числа приводим к number
// (десятичная запятая -> точка), строки с пустым наименованием выбрасываем.
// Сырой ответ сохраняем целиком — уйдёт в docs.invoices.raw_json.
const resp = $input.first().json;
const ctx = $('Build VLM request').first().json;
if (resp.error) {
  throw new Error('OLLAMA_FAIL: ' + JSON.stringify(resp.error).slice(0, 400));
}
let content = (resp.message && resp.message.content) || '';
content = content.replace(/```json|```/g, '').trim();
let data;
try {
  data = JSON.parse(content);
} catch (e) {
  throw new Error('PARSE_FAIL: ' + e.message + ' | ' + content.slice(0, 300));
}
if (!data || !Array.isArray(data.items)) {
  throw new Error('PARSE_FAIL: в ответе нет массива items');
}
const num = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};
const items = data.items.map((it, i) => ({
  line_no: Number.isInteger(it.line_no) ? it.line_no : i + 1,
  item_name: String(it.item_name ?? '').trim(),
  unit: it.unit == null ? null : String(it.unit).trim(),
  quantity: num(it.quantity),
  price: num(it.price)
})).filter(it => it.item_name);
const esc = s => String(s).replace(/'/g, "''");
return { json: {
  doc_id: ctx.doc_id,
  file_name: ctx.file_name,
  file_name_sql: esc(ctx.file_name),
  raw_sql: esc(content),
  items,
  items_count: items.length
} };

// Мультистроковый INSERT позиций. Строки экранируем (кавычки),
// NULL — без кавычек. invoice_id — из Upsert invoice.
const inv = $('Upsert invoice').first().json;
const parsed = $('Parse & validate').first().json;
const esc = s => String(s).replace(/'/g, "''");
const vals = parsed.items.map(it =>
  `(${inv.id}, ${it.line_no}, '${esc(it.item_name)}', ` +
  `${it.unit === null ? 'NULL' : `'${esc(it.unit)}'`}, ` +
  `${it.quantity === null ? 'NULL' : it.quantity}, ` +
  `${it.price === null ? 'NULL' : it.price})`
).join(',\n');
return { json: { invoice_id: inv.id, values_sql: vals } };

