DELETE FROM docs.invoice_items
WHERE invoice_id = {{ $json.invoice_id }};

UPDATE docs.documents
SET status = 'done', status_changed_at = now(), processed_at = now(), error_message = NULL
WHERE id = '{{ $('Parse & validate').first().json.doc_id }}'::bigint;

