// Сбор ошибки из любой упавшей ветки -> status='error'.
const err = $input.first().json;
const msg = (err.error && (err.error.message || JSON.stringify(err.error)))
  || err.message || JSON.stringify(err);
const body = $('Webhook').first().json.body;
return { json: {
  doc_id: body.doc_id,
  error_sql: String(msg).replace(/'/g, "''").slice(0, 900)
} };
